using System;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.Rendering.RenderGraphModule;using UnityEngine.Experimental.Rendering;
public static class Eye206R2Layers{
 public static bool Enabled;public static Eye206R2View Current;public static readonly string[]Names={"Eye0_White","Eye0_IrisPupil","Eye1_White","Eye1_IrisPupil"};
 public sealed class Set:IDisposable{public RTHandle rgba,meta,world,uv,depth;public Set(string n){rgba=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R8G8B8A8_SRGB,filterMode:FilterMode.Point,name:n+"RGBA");meta=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"Meta");world=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"World");uv=RTHandles.Alloc(960,544,colorFormat:GraphicsFormat.R32G32B32A32_SFloat,filterMode:FilterMode.Point,name:n+"UV");depth=RTHandles.Alloc(960,544,depthBufferBits:DepthBits.Depth32,filterMode:FilterMode.Point,name:n+"Depth");}public void Dispose(){rgba?.Release();meta?.Release();world?.Release();uv?.Release();depth?.Release();}}
 public static Set[]Sets;public static void Ensure(){if(Sets==null)Sets=Names.Select(n=>new Set("205"+n)).ToArray();}public static void Dispose(){Enabled=false;Current=null;if(Sets!=null)foreach(var s in Sets)s.Dispose();Sets=null;}
}
public sealed class Eye206R2PartFeature:ScriptableRendererFeature{
 PartPass pass;public override void Create(){pass=new PartPass{renderPassEvent=RenderPassEvent.AfterRenderingTransparents};}public override void AddRenderPasses(ScriptableRenderer r,ref RenderingData d){var v=Eye206R2Layers.Current;if(Eye206R2Layers.Enabled&&v&&d.cameraData.camera==v.Layers.game.actor.inheritedView.worldCamera)r.EnqueuePass(pass);}
 sealed class Data{public Renderer renderer;public Material material;}
 sealed class PartPass:ScriptableRenderPass{public override void RecordRenderGraph(RenderGraph g,ContextContainer frame){Eye206R2Layers.Ensure();var v=Eye206R2Layers.Current;for(int i=0;i<4;i++){using var b=g.AddRasterRenderPass<Data>("205 actual attached "+Eye206R2Layers.Names[i],out var d);var t=Eye206R2Layers.Sets[i];b.SetRenderAttachment(g.ImportTexture(t.rgba),0,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.meta),1,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.world),2,AccessFlags.Write);b.SetRenderAttachment(g.ImportTexture(t.uv),3,AccessFlags.Write);b.SetRenderAttachmentDepth(g.ImportTexture(t.depth),AccessFlags.Write);b.UseAllGlobalTextures(true);b.AllowPassCulling(false);b.AllowGlobalStateModification(true);d.renderer=v.carriers[i];d.material=d.renderer.sharedMaterial;b.SetRenderFunc(static(Data d,RasterGraphContext c)=>{c.cmd.ClearRenderTarget(RTClearFlags.All,Color.clear,1,0);int p=d.material.FindPass("Eye205Independent");if(p<0)throw new Exception("205 independent pass missing");c.cmd.DrawRenderer(d.renderer,d.material,0,p);});}}}
}
